#minacoding #generativeart #creativecoding #p5js
*/ 

const S = 50;
const CLRS = "6b2737-e08e45-f8f4a6-bdf7b7-3943b7"
  .split("-")
  .map((i) => "#" + i);
let BG = "#000008";
let x = 0, y = S;

function setup() {
  createCanvas(400, 400);
	describe("animation of lines of quarter circles in different sizes and orientation fading out and overlapping with previous lines")
  frameRate(60);
  noStroke();
  background(BG);
	BG += "04";
}

function draw() {
	blendMode(BLEND)
	background(BG); // semi transparent

	blendMode(DIFFERENCE)
  if (frameCount % 10 === 0) {
		let minH = S;
		while (x < width) {
			const s = ~~random(S/2, S);
			if (s < minH) minH = s;
			drawTile(x + s/2, y+(S-s)/2, s);
			x += s;			
		}
		if (x >= width) {
			x = 0;
			y += minH; // S;
			if (y > height) {
				y = S;
			}
		}
	}

  push();
	blendMode(BLEND)
  stroke(0);
  fill(255);
  text("#minacoding 24/05 Many", 0, 10);
  pop();
}

function drawTile(x, y, S) {
  push();
  translate(x, y);
  fill(BG);
  rectMode(CENTER);
  rect(0, 0, S);
  rotate(~~random(4) * HALF_PI);
  translate(S / 2, S / 2);
  fill(random(CLRS));
  arc(0, 0, S * 2, S * 2, PI, TWO_PI - HALF_PI);
	if (random() < 0.4) {
		fill(random(CLRS));
		arc(0, 0, S, S, PI, TWO_PI - HALF_PI);		
	}
  pop();
}
